  "steps": [
    {
      "id": 1,
      "claim": "Stream velocity determines the kinetic energy and shear stress available for moving sediment.",
      "evidence": "Fluid dynamics: kinetic energy ∝ v² and shear stress τ = ρ g R S is proportional to velocity.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "When velocity decreases, the shear stress falls below the critical shear stress needed to keep many particles in motion.",
      "evidence": "Critical shear stress concept; particles are entrained only if τ > τ_crit.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Particles whose settling velocity exceeds the reduced flow velocity will no longer be entrained and will settle to the bed, producing deposition.",
      "evidence": "Settling velocity vs. flow velocity relationship; Hjulström curve shows that as velocity drops, particles of a given size transition from transport to deposition. Even if fine colloids may stay suspended, the net flux of most sediment shifts toward settling.",
      "weight": 0.30,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Therefore, a decrease in stream velocity leads to an increase in deposition of material in the stream.",
      "evidence": "Logical consequence of step 3: more particles settle per unit time.",
      "weight": 0.20,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Erosion of the stream bank requires sufficient shear stress; lower velocity reduces this stress, so erosion decreases.",
      "evidence": "Bank erosion models link erosion rate to τ; when τ < τ_crit for bank material, erosion ceases.",
      "weight": 0.05,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "The total amount of material that can be carried downstream (capacity) declines as velocity decreases.",
      "evidence": "Empirical relationships: capacity ∝ v⁴–v⁵ (e.g., Meyer‑Peter‑Müller formula).",
      "weight": 0.05,
      "depends_on": [1]
    },
    {
      "id": 7,
      "claim": "The maximum particle size that can be transported downstream (competence) also declines with lower velocity.",
      "evidence": "Competence is a function of velocity; larger particles require higher velocities to be moved (Hjulström curve).",
      "weight": 0.05,
      "depends_on": [1]
    }
  ],
  "considered": [
